import { useOnyxQuery } from '../../hooks/useQuery';
import type { ReportProjection } from '../../types/query';
import StatusBadge from '../../components/StatusBadge';

export default function ReportsPage() { const query = useOnyxQuery<ReportProjection>('report.detail'); const report = query.data?.data[0]; return <div className="page-stack"><header className="page-header"><div><p className="eyebrow">Evidence viewer</p><h1>Reports</h1><p>Read-only access to published report projections and attachment references.</p></div></header>{report ? <article className="report-document"><div className="report-heading"><div><p className="eyebrow">Operational report</p><h2>{report.title}</h2><p>Prepared by {report.author} · {new Date(report.submitted_at).toLocaleString()}</p></div><StatusBadge status={report.status} /></div><section><h3>Summary</h3><p>{report.summary}</p></section><section><h3>Evidence references</h3><div className="evidence-list">{report.evidence.map((item) => <div className="evidence-item" key={item.file_name}><div><strong>{item.label}</strong><span>{item.file_name}</span></div><span className="read-only-pill">View only</span></div>)}</div></section><footer>Projection version {report.version} · Updated {new Date(report.updated_at).toLocaleString()}</footer></article> : <div className="empty-state"><h2>No published report</h2><p>The report projection is unavailable.</p></div>}</div>; }
